using Microsoft.Xna.Framework;

namespace ChainsawManMod.Content.Players
{
	// The rows of ChainsawDevilSheet.png, top to bottom.
	public enum DevilAnim
	{
		Idle,
		Walk,
		Run,
		Jump,
		Crouch,
		Attack1,
		Attack2,
		Attack3,
		Attack4,
		Attack5,
		AirAttack1,
		AirAttack2,
		AirAttack3,
		Damage
	}

	// Layout of ChainsawDevilSheet.png (generated by tools/clean_sprite_sheet.py).
	// Every frame sits in a CellWidth x CellHeight cell, with the character's feet at the bottom centre of the cell.
	public static class ChainsawDevilAnimation
	{
		public const string TexturePath = "ChainsawManMod/Content/Players/ChainsawDevilSheet";
		public const int CellWidth = 94;
		public const int CellHeight = 58;

		// Frames per row, in DevilAnim order.
		private static readonly int[] FrameCounts = { 6, 8, 8, 7, 5, 8, 7, 13, 6, 8, 5, 5, 6, 9 };

		public static readonly DevilAnim[] GroundAttacks = { DevilAnim.Attack1, DevilAnim.Attack2, DevilAnim.Attack3, DevilAnim.Attack4, DevilAnim.Attack5 };
		public static readonly DevilAnim[] AirAttacks = { DevilAnim.AirAttack1, DevilAnim.AirAttack2, DevilAnim.AirAttack3 };

		public static int FrameCount(DevilAnim anim) => FrameCounts[(int)anim];

		public static Rectangle GetFrame(DevilAnim anim, int frame) {
			return new Rectangle(frame * CellWidth, (int)anim * CellHeight, CellWidth, CellHeight);
		}
	}
}
